# ------------------------------------------------------------------ arquivos do menu
GAMELISTS = ""


def embedded_gamelists():
    """Os textos dos jogos que vem dentro deste programa: {nome do arquivo: texto}."""
    import base64, zlib, json
    if GAMELISTS.startswith('@@'):
        return {}
    return json.loads(zlib.decompress(base64.b64decode(GAMELISTS)).decode('utf-8'))


def card_ode(root):
    """as chaves do .config/ngcdconfig.ode (o menu grava)."""
    d = {}
    try:
        for ln in open(os.path.join(root, '.config', 'ngcdconfig.ode'), encoding='utf-8', errors='replace'):
            if '=' in ln and not ln.startswith('#'):
                k, v = ln.rstrip('\r\n').split('=', 1); d[k.strip()] = v.strip()
    except OSError:
        pass
    return d


def card_lang(root):
    """O idioma do menu do cartao: 'pt', 'es' ou 'en' (ngcdconfig.ode; antes, o _NGCCONFIG.SAV)."""
    v = card_ode(root).get('idioma', '').lower()
    if v:
        return 'es' if v.startswith('esp') else 'en' if v.startswith('eng') else 'pt'
    for name in ('_NGCCONFIG.SAV', '_NSDLMNU.SAV'):
        try:
            b = open(os.path.join(root, name), 'rb').read()
            if b[:4] == b'CRMN' and struct.unpack('>H', b[4:6])[0] >= 4:
                return ('pt', 'es', 'en')[b[8 + 16]] if b[8 + 16] < 3 else 'pt'
        except Exception:
            pass
    return 'pt'


def card_loader(root):
    """versao do loader do console (o menu grava info_loader no ngcdconfig.ode); 0 = nao sei."""
    try:
        return int(card_ode(root).get('info_loader', '0'))
    except ValueError:
        return 0


def gamelists(midias, lang):
    """gamelist.<idioma>.txt e gamelist.dat: da pasta das midias (ou da subpasta gamelist) se houver;
    senao, os que vem dentro deste programa."""
    for d in (os.path.join(midias, 'gamelist'), midias):
        gl, dat = load_gamelists(d, lang)
        if gl:
            if not dat:
                emb = embedded_gamelists()
                dat = parse_dat(emb.get('gamelist.dat', ''))
            return gl, dat, d
    emb = embedded_gamelists()
    txt = emb.get('gamelist.%s.txt' % lang) or emb.get('gamelist.pt.txt', '')
    return parse_gamelist(txt), parse_dat(emb.get('gamelist.dat', '')), '(embutido)'


def menu_files():
    """Os arquivos do menu (sem o MEDIA.PRG e sem capas): os embutidos neste programa."""
    raw = zlib.decompress(base64.b64decode(MENU_FILES_B64))
    out, o = [], 0
    while o < len(raw):
        n = raw[o]; name = raw[o + 1:o + 1 + n].decode('ascii'); o += 1 + n
        size = struct.unpack_from('>I', raw, o)[0]; o += 4
        out.append((name, raw[o:o + size])); o += size
    return out


def iso_files(path):
    """Le os arquivos da raiz de um ISO 9660 (para aproveitar um BOOT.ISO mais novo do cartao)."""
    d = open(path, 'rb').read()
    S = 2048
    if d[16 * S + 1:16 * S + 6] != b'CD001':
        return None
    root = d[16 * S + 156:16 * S + 190]
    lba, size = struct.unpack_from('<I', root, 2)[0], struct.unpack_from('<I', root, 10)[0]
    out, o = [], lba * S
    end = o + size
    while o < end:
        ln = d[o]
        if ln == 0:
            o = (o // S + 1) * S
            continue
        fl, fs = struct.unpack_from('<I', d, o + 2)[0], struct.unpack_from('<I', d, o + 10)[0]
        nl = d[o + 32]
        name = d[o + 33:o + 33 + nl].decode('ascii', 'ignore').split(';')[0]
        if name not in ('\0', '\1') and not (d[o + 25] & 2):
            out.append((name, d[fl * S:fl * S + fs]))
        o += ln
    return out


def is_media_file(name):
    return name == 'MEDIA.PRG' or re.match(r'^([CSV]\d{4}\.(PRG|SPR)|[DGK]\d{4}\.PRG|V\d{4}[A-Z]\.PRG)$', name) is not None


def menu_version(files):
    """Versao do menu: o texto "MENU n" dentro do BOOT.PRG."""
    for n, d in files:
        if n == 'BOOT.PRG':
            m = re.search(rb'MENU (\d+)', d)
            return int(m.group(1)) if m else 0
    return 0


# ------------------------------------------------------------------ jogos e imagens
def find_dir(base, names):
    try:
        for d in sorted(os.listdir(base)):
            if d.lower() in names and os.path.isdir(os.path.join(base, d)):
                return os.path.join(base, d)
    except OSError:
        pass
    return None


def games_of(root):
    """Pastas da raiz com um .cue dentro (o jeito que o SD Loader acha os jogos)."""
    out = []
    for d in sorted(os.listdir(root), key=str.lower):
        p = os.path.join(root, d)
        if not os.path.isdir(p) or d.startswith(('_', '.')) or d.lower() in SKIP:
            continue
        try:
            if any(f.lower().endswith('.cue') for f in os.listdir(p)):
                out.append(d)
        except OSError:
            pass
    return out


def images_of(d, exts=None):
    exact, loose = {}, {}
    if d and os.path.isdir(d):
        for f in os.listdir(d):
            b, e = os.path.splitext(f)
            if e.lower() in (exts or IMG_EXT) and not f.startswith('._'):
                p = os.path.join(d, f)
                exact.setdefault(b.lower(), p)
                loose.setdefault(norm(b), []).append(p)
    return exact, loose


def find_image(maps, name):
    exact, loose = maps
    p = exact.get(name.lower())
    if p:
        return p
    c = loose.get(norm(name))
    if c:
        return sorted(c, key=len)[0]
    key = norm(name)
    # pelo nome sem o subtitulo de um dos lados (so quando um dos dois nao tem subtitulo):
    # "Art of Fighting 3" = "Art of Fighting 3 - The Path of the Warrior (World)"
    base = lambda n: norm(re.split(r'\s+-\s+|:\s+', re.sub(r'[\(\[][^\)\]]*[\)\]]', ' ', n))[0])
    for k, ps in loose.items():
        for p_ in ps:
            if base(os.path.splitext(os.path.basename(p_))[0]) == key:
                return p_
    gb = base(name)
    if gb != key and gb in loose:
        return sorted(loose[gb], key=len)[0]
    close = difflib.get_close_matches(key, list(loose), n=1, cutoff=0.9)
    if close and re.findall(r'\d+', close[0]) == re.findall(r'\d+', key) and abs(len(close[0]) - len(key)) <= 2:
        return loose[close[0]][0]
    return None


def read_links(root):
    """.boot/LINKS.TXT (a pagina grava; antes ficava em _BOOT): pasta<TAB>jogo. A pasta pega capa, tela, video e texto desse jogo."""
    links = {}
    for bd in ('.boot', '_BOOT'):
        try:
            for ln in open(os.path.join(root, bd, 'LINKS.TXT'), encoding='utf-8', errors='replace'):
                a, _, b = ln.rstrip('\r\n').partition('\t')
                if a and b.strip():
                    links[norm(a)] = b.strip()
            break
        except OSError:
            pass
    return links


def remote_index():
    try:
        tree = json.load(urllib.request.urlopen(urllib.request.Request(API, headers=UA), timeout=20))
        idx = {'Named_Boxarts': {}, 'Named_Snaps': {}}
        for t in tree.get('tree', []):
            p = t.get('path', '')
            for k in idx:
                if p.startswith(k + '/') and p.lower().endswith('.png'):
                    b = p[len(k) + 1:-4]
                    idx[k].setdefault(norm(b), []).append(b)
        return idx
    except Exception as e:
        print('  (nao consegui listar o libretro-thumbnails: %s)' % e)
        return None


def remote_find(idx, folder, name):
    t = idx[folder]
    key = norm(name)
    if key in t:
        return sorted(t[key], key=len)[0]
    close = difflib.get_close_matches(key, list(t), n=1, cutoff=0.88)
    if close and re.findall(r'\d+', close[0]) == re.findall(r'\d+', key) and abs(len(close[0]) - len(key)) <= 2:
        return sorted(t[close[0]], key=len)[0]
    return None


def download(folder, base, dest):
    url = RAW + folder + '/' + urllib.parse.quote(base + '.png')
    data = urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=30).read()
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    open(dest, 'wb').write(data)


# ====================================================================== DISCOS (CHD, NRG, IMG/CCD, ISO+MP3...)
# O SD Loader so le uma pasta na raiz com um .cue dentro (cue_sheet.c do MCU):
#   - TRACK 01 tem que ser MODE1/2048 ou MODE1/2352 (o arquivo pode ser .iso ou .bin)
#   - as outras faixas: AUDIO em BINARY (PCM cru) ou WAVE (o MCU pula 44 bytes fixos de cabecalho)
#   - a posicao da faixa (INDEX 01) e multiplicada por 2048 no WAVE e pelo tamanho do setor da faixa 1 no BINARY
#   - linhas so com espacos no comeco (TAB nao)
# Aqui tudo vira isso: .chd (chdman), .nrg (Nero), .img + .ccd (CloneCD), .img/.bin soltos, .iso + faixas de
# audio (mp3/ogg/flac... viram .wav), .zip/.7z (extrai). O original fica (so apaga com --apagar-origem).
import shutil, subprocess, array, zipfile

DISC_EXT = ('.cue', '.iso', '.chd', '.nrg', '.img', '.ccd', '.sub', '.bin', '.zip', '.7z', '.mds', '.mdf', '.wav', '.mp3',
            '.ogg', '.flac', '.ape', '.opus', '.m4a', '.wv')
AUDIO_CONV_EXT = ('.mp3', '.ogg', '.flac', '.ape', '.opus', '.m4a', '.wv', '.aac', '.wma')
SYNC = b'\x00' + b'\xff' * 10 + b'\x00'


def msf(frames):
    return '%02d:%02d:%02d' % (frames // 4500, frames // 75 % 60, frames % 75)


def msf_frames(t):
    m, s, f = (int(x) for x in t.split(':'))
    return (m * 60 + s) * 75 + f


_FF = [None]


def ffmpeg():
    """o ffmpeg: no PATH, ao lado deste programa, ou o do imageio-ffmpeg (instalado sozinho)."""
    if _FF[0]:
        return _FF[0]
    here = os.path.dirname(os.path.abspath(sys.argv[0] or __file__))
    for c in (shutil.which('ffmpeg'), os.path.join(here, 'ffmpeg.exe'), os.path.join(here, 'ffmpeg')):
        if c and os.path.isfile(c):
            _FF[0] = c; return c
    m = _ensure_pkg('imageio-ffmpeg', 'imageio_ffmpeg')
    if m:
        try:
            _FF[0] = m.get_ffmpeg_exe(); return _FF[0]
        except Exception:
            pass
    return None


def chdman():
    here = os.path.dirname(os.path.abspath(sys.argv[0] or __file__))
    w = shutil.which('chdman') or shutil.which('chdman.exe')
    if w:
        return w
    for base in (here, os.path.join(here, 'tools'), os.path.join(here, '..'), os.path.join(here, '..', 'tools')):
        for nm in ('chdman.exe', 'chdman'):
            p = os.path.join(base, nm)
            if os.path.isfile(p):
                return p
    return None


def wav_bytes(pcm):
    """WAV com o cabecalho de 44 bytes que o MCU espera (PCM 16 bits, 44100 Hz, estereo)."""
    return (b'RIFF' + struct.pack('<I', 36 + len(pcm)) + b'WAVEfmt ' + struct.pack('<IHHIIHH', 16, 1, 2, 44100, 176400, 4, 16) +
            b'data' + struct.pack('<I', len(pcm)) + pcm)


def wav_info(path):
    """(posicao dos dados, tamanho) de um .wav PCM 16 bits 44100 estereo; None se for outro formato. So le o cabecalho."""
    with open(path, 'rb') as f:
        d = f.read(65536)
    if d[:4] != b'RIFF' or d[8:12] != b'WAVE':
        return None
    o, fmt = 12, None
    while o + 8 <= len(d):
        cid, n = d[o:o + 4], struct.unpack_from('<I', d, o + 4)[0]
        if cid == b'fmt ':
            fmt = struct.unpack_from('<HHIIHH', d, o + 8)
        elif cid == b'data':
            if not fmt or fmt[0] != 1 or fmt[1] != 2 or fmt[2] != 44100 or fmt[5] != 16:
                return None
            return o + 8, min(n, os.path.getsize(path) - o - 8)
        o += 8 + n + (n & 1)
    return None


def wav_pcm(path):
    w = wav_info(path)
    if not w:
        return None
    with open(path, 'rb') as f:
        f.seek(w[0]); return f.read(w[1])


def decode_audio(path):
    """qualquer audio -> PCM 16 bits 44100 estereo (pelo ffmpeg)."""
    ff = ffmpeg()
    if not ff:
        raise RuntimeError('preciso do ffmpeg para converter %s' % os.path.basename(path))
    r = subprocess.run([ff, '-v', 'error', '-i', path, '-f', 's16le', '-acodec', 'pcm_s16le', '-ar', '44100', '-ac', '2', '-'],
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if r.returncode != 0:
        raise RuntimeError('ffmpeg: ' + r.stderr.decode('utf-8', 'ignore')[-160:])
    return r.stdout


def audio_swapped(pcm):
    """1 se o PCM parece estar com os bytes trocados (big-endian): o audio certo varia pouco de uma amostra para outra."""
    n = min(len(pcm), 2 * 1024 * 1024) // 4 * 4
    if n < 4096:
        return False
    a = array.array('h', pcm[:n]); b = array.array('h', pcm[:n]); b.byteswap()
    if sys.byteorder == 'big':
        a, b = b, a
    da = sum(abs(a[i] - a[i - 2]) for i in range(2, len(a), 7))
    db = sum(abs(b[i] - b[i - 2]) for i in range(2, len(b), 7))
    return db * 3 < da


# ---------------------------------------------------------------- o .cue como lista: [arquivo, tipo, [faixas]]
def cue_read(path):
    files, cur, trk = [], None, None
    for ln in open(path, encoding='utf-8', errors='replace').read().splitlines():
        s = ln.strip()
        u = s.upper()
        if u.startswith('FILE '):
            m = re.match(r'FILE\s+"([^"]+)"\s*(\S*)', s, re.I) or re.match(r'FILE\s+(\S+)\s*(\S*)', s, re.I)
            cur = [m.group(1), (m.group(2) or 'BINARY').upper(), []]
            files.append(cur)
        elif u.startswith('TRACK ') and cur is not None:
            p = s.split()
            trk = {'n': int(p[1]), 'type': p[2].upper() if len(p) > 2 else 'MODE1/2352', 'idx': {}}
            cur[2].append(trk)
        elif u.startswith('INDEX ') and trk is not None:
            p = s.split()
            trk['idx'][int(p[1])] = msf_frames(p[2])
    return files


def cue_text(files):
    out = []
    for name, typ, trks in files:
        out.append('FILE "%s" %s' % (name, typ))
        for t in trks:
            out.append('  TRACK %02d %s' % (t['n'], t['type']))
            for i in sorted(t['idx']):
                out.append('    INDEX %02d %s' % (i, msf(t['idx'][i])))
    return '\r\n'.join(out) + '\r\n'


def find_file(folder, name):
    """o arquivo citado no .cue (sem diferenca de maiuscula; se nao achar, o de mesmo nome com outra extensao de audio)."""
    p = os.path.join(folder, name)
    if os.path.isfile(p):
        return p
    lst = os.listdir(folder)
    for f in lst:
        if f.lower() == os.path.basename(name).lower():
            return os.path.join(folder, f)
    stem = os.path.splitext(os.path.basename(name))[0].lower()
    for f in lst:
        b, e = os.path.splitext(f)
        if b.lower() == stem and e.lower() in AUDIO_CONV_EXT + ('.wav', '.bin'):
            return os.path.join(folder, f)
    return None


def cue_fix(folder, cue, dry, log, fresh=False):
    """Confere o .cue para o SD Loader e conserta o que precisar (audio vira .wav com 44 bytes de cabecalho)."""
    files = cue_read(cue)
    tracks = [(f, t) for f in files for t in f[2]]
    if not tracks:
        log('  %s: .cue sem faixas' % os.path.basename(cue)); return False
    t1 = tracks[0][1]
    if t1['n'] != 1 or t1['type'] not in ('MODE1/2048', 'MODE1/2352'):
        log('  %s: a faixa 1 e %s (o SD Loader so le MODE1/2048 ou MODE1/2352)' % (os.path.basename(cue), t1['type']))
        return False
    sec1 = 2048 if t1['type'] == 'MODE1/2048' else 2352
    changed = False
    for f in files:
        p = find_file(folder, f[0])
        if not p:
            log('  %s: falta o arquivo %s' % (os.path.basename(cue), f[0])); return False
        if os.path.basename(p) != f[0]:
            f[0] = os.path.basename(p); changed = True
    new_files = []
    for f in files:
        p, ext = os.path.join(folder, f[0]), os.path.splitext(f[0])[1].lower()
        audio = [t for t in f[2] if t['type'] == 'AUDIO']
        data = [t for t in f[2] if t['type'] != 'AUDIO']
        if not audio:
            new_files.append(f); continue
        conv = ext in AUDIO_CONV_EXT or f[1] not in ('BINARY', 'WAVE')
        if f[1] == 'WAVE' and not conv:
            w = wav_info(p)
            conv = w is None or w[0] != 44 or any(t['idx'].get(1, 0) for t in audio)
        if f[1] == 'BINARY' and not conv and sec1 == 2048 and any(t['idx'].get(1, 0) for t in audio):
            conv = True     # o MCU multiplica por 2048 (o setor da faixa 1): a posicao sairia errada
        if not conv:
            new_files.append(f); continue
        if data:
            log('  %s: dados e audio no mesmo arquivo com faixa 1 de 2048: nao sei separar' % os.path.basename(cue)); return False
        # uma faixa por .wav, comecando no INDEX 01
        if dry:
            log('  [teste] converteria o audio de %s para .wav' % f[0]); new_files.append(f); continue
        if ext in AUDIO_CONV_EXT or f[1] not in ('BINARY', 'WAVE'):
            pcm = decode_audio(p)
        elif f[1] == 'WAVE':
            pcm = wav_pcm(p)
            if pcm is None:
                pcm = decode_audio(p)
        else:
            pcm = open(p, 'rb').read()
            if audio_swapped(pcm):
                a = array.array('h', pcm[:len(pcm) // 2 * 2]); a.byteswap(); pcm = a.tobytes()
        for k, t in enumerate(audio):
            a0 = t['idx'].get(1, 0) * 2352
            a1 = audio[k + 1]['idx'].get(0, audio[k + 1]['idx'].get(1)) * 2352 if k + 1 < len(audio) else len(pcm)
            nm = os.path.splitext(f[0])[0] + ('' if len(audio) == 1 else ' (%02d)' % t['n']) + '.wav'
            if nm.lower() == f[0].lower():
                nm = os.path.splitext(f[0])[0] + ' (ngcd).wav'
            open(os.path.join(folder, nm), 'wb').write(wav_bytes(pcm[a0:a1]))
            new_files.append([nm, 'WAVE', [{'n': t['n'], 'type': 'AUDIO', 'idx': {1: 0}}]])
        log('  audio %s -> .wav' % f[0])
        changed = True
    raw = open(cue, 'rb').read()
    if b'\t' in raw or b'\r\n' not in raw:
        changed = True
    if changed and not dry:
        bak = cue + '.orig'
        if not fresh and not os.path.exists(bak):
            shutil.copy2(cue, bak)
        open(cue, 'w', encoding='utf-8', newline='').write(cue_text(new_files))
        if not fresh:
            log('  %s acertado (o original ficou como .cue.orig)' % os.path.basename(cue))
    return True


# ---------------------------------------------------------------- conversoes
def chd_to_cue(chd, log):
    cm = chdman()
    if not cm:
        log('  %s: preciso do chdman (vem com o MAME): ponha o chdman.exe ao lado do generate_usb' % os.path.basename(chd))
        return None
    base = os.path.splitext(chd)[0]
    r = subprocess.run([cm, 'extractcd', '-i', chd, '-o', base + '.cue', '-ob', base + '.bin', '-f'],
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    if r.returncode != 0:
        log('  chdman falhou: ' + r.stdout.decode('utf-8', 'ignore')[-160:]); return None
    return base + '.cue'


def nrg_to_cue(nrg, log):
    """Nero (.nrg): le o rodape (NER5/NERO) e o bloco DAOX/DAOI; grava uma faixa por arquivo."""
    f = open(nrg, 'rb'); f.seek(0, 2); size = f.tell()
    f.seek(size - 12); tail = f.read(12)
    if tail[:4] == b'NER5':
        off, wide = struct.unpack('>Q', tail[4:])[0], True
    elif tail[4:8] == b'NERO':
        off, wide = struct.unpack('>I', tail[8:])[0], False
    else:
        log('  %s: nao parece um .nrg' % os.path.basename(nrg)); return None
    f.seek(off); chunks = f.read(size - off)
    o, dao = 0, None
    while o + 8 <= len(chunks):
        cid, n = chunks[o:o + 4], struct.unpack_from('>I', chunks, o + 4)[0]
        if cid in (b'DAOX', b'DAOI') and dao is None:
            dao = (cid, chunks[o + 8:o + 8 + n])
        if cid == b'END!':
            break
        o += 8 + n
    if not dao:
        log('  %s: .nrg sem DAO (gravado em TAO): nao sei converter' % os.path.basename(nrg)); return None
    cid, d = dao
    first, last = d[20], d[21]
    ent = 42 if cid == b'DAOX' else 30
    base = os.path.splitext(nrg)[0]
    files = []
    for k in range(last - first + 1):
        e = d[22 + k * ent:22 + (k + 1) * ent]
        ssz, mode = struct.unpack_from('>H', e, 12)[0], e[14]
        if cid == b'DAOX':
            i0, i1, end = struct.unpack_from('>QQQ', e, 18)
        else:
            i0, i1, end = struct.unpack_from('>III', e, 18)
        n = first + k
        f.seek(i1); raw = f.read(end - i1)
        if ssz in (2448, 2368):      # com subcanal: so os 2352 de cada setor
            raw = b''.join(raw[i:i + 2352] for i in range(0, len(raw), ssz))
            ssz = 2352
        audio = mode == 7 or (n > 1 and ssz == 2352 and raw[:12] != SYNC)
        if audio:
            if audio_swapped(raw):
                a = array.array('h', raw[:len(raw) // 2 * 2]); a.byteswap(); raw = a.tobytes()
            nm = '%s (Track %02d).bin' % (os.path.basename(base), n)
            files.append([nm, 'BINARY', [{'n': n, 'type': 'AUDIO', 'idx': {1: 0}}]])
        else:
            if ssz not in (2048, 2352):
                log('  %s: faixa %d com setor de %d bytes: nao suportado' % (os.path.basename(nrg), n, ssz)); return None
            nm = '%s (Track %02d).%s' % (os.path.basename(base), n, 'iso' if ssz == 2048 else 'bin')
            files.append([nm, 'BINARY', [{'n': n, 'type': 'MODE1/%d' % ssz, 'idx': {1: 0}}]])
        open(os.path.join(os.path.dirname(nrg), nm), 'wb').write(raw)
    f.close()
    cue = base + '.cue'
    open(cue, 'w', encoding='utf-8', newline='').write(cue_text(files))
    return cue


def ccd_to_cue(ccd, img, log):
    """CloneCD (.ccd + .img): o .img e o disco inteiro em setores de 2352; o .ccd tem as faixas."""
    trk, cur = {}, None
    for ln in open(ccd, encoding='latin-1').read().splitlines():
        s = ln.strip()
        m = re.match(r'\[TRACK\s+(\d+)\]', s, re.I)
        if m:
            cur = trk.setdefault(int(m.group(1)), {'mode': 1, 'idx': {}}); continue
        if s.startswith('['):
            cur = None; continue
        if cur is not None and '=' in s:
            k, v = (x.strip() for x in s.split('=', 1))
            if k.upper() == 'MODE':
                cur['mode'] = int(v)
            m = re.match(r'INDEX\s+(\d+)', k, re.I)
            if m:
                cur['idx'][int(m.group(1))] = int(v, 0)
    if not trk:
        log('  %s: .ccd sem faixas' % os.path.basename(ccd)); return None
    ts = [{'n': n, 'type': 'AUDIO' if trk[n]['mode'] == 0 else 'MODE1/2352' if trk[n]['mode'] == 1 else 'MODE2/2352',
           'idx': trk[n]['idx']} for n in sorted(trk)]
    cue = os.path.splitext(img)[0] + '.cue'
    open(cue, 'w', encoding='utf-8', newline='').write(cue_text([[os.path.basename(img), 'BINARY', ts]]))
    return cue


def raw_to_cue(path, log, audio=()):
    """.iso/.img/.bin sozinho (com ou sem faixas de audio ao lado): um .cue novo."""
    with open(path, 'rb') as f:
        head = f.read(16)
    ssz = 2352 if head[:12] == SYNC else 2048
    files = [[os.path.basename(path), 'BINARY', [{'n': 1, 'type': 'MODE1/%d' % ssz, 'idx': {1: 0}}]]]
    for k, a in enumerate(audio):
        typ = 'WAVE' if a.lower().endswith('.wav') else 'BINARY' if a.lower().endswith('.bin') else 'MP3'
        files.append([a, typ, [{'n': k + 2, 'type': 'AUDIO', 'idx': {1: 0}}]])
    cue = os.path.splitext(path)[0] + '.cue'
    open(cue, 'w', encoding='utf-8', newline='').write(cue_text(files))
    return cue


def extract_archive(p, folder, log):
    try:
        if p.lower().endswith('.zip'):
            with zipfile.ZipFile(p) as z:
                z.extractall(folder)
        else:
            m = _ensure_pkg('py7zr', 'py7zr')
            if not m:
                log('  %s: instale o py7zr (py -m pip install py7zr) ou extraia voce' % os.path.basename(p)); return False
            with m.SevenZipFile(p, 'r') as z:
                z.extractall(folder)
    except Exception as e:
        log('  %s: nao consegui extrair (%s)' % (os.path.basename(p), str(e)[:80])); return False
    # se veio tudo dentro de uma pasta, sobe um nivel
    subs = [d for d in os.listdir(folder) if os.path.isdir(os.path.join(folder, d))]
    if len(subs) == 1 and not any(f.lower().endswith(('.cue', '.iso', '.chd', '.nrg', '.img', '.bin')) for f in os.listdir(folder)):
        sd = os.path.join(folder, subs[0])
        for f in os.listdir(sd):
            if not os.path.exists(os.path.join(folder, f)):
                shutil.move(os.path.join(sd, f), os.path.join(folder, f))
    return True


def _num_key(s):
    return [int(x) if x.isdigit() else x.lower() for x in re.split(r'(\d+)', s)]


def disc_folder(folder, dry, delete_src, log):
    """Deixa a pasta do jogo com um .cue que o SD Loader le. Devolve True se a pasta e um jogo pronto."""
    name = os.path.basename(folder)
    lst = lambda: sorted(os.listdir(folder), key=_num_key)
    ext_of = lambda e: [f for f in lst() if f.lower().endswith(e) and not f.startswith('._')]
    if not ext_of('.cue') and not ext_of('.chd') and not ext_of('.nrg') and not ext_of('.iso') and not ext_of('.img') and not ext_of('.bin'):
        for a in ext_of('.zip') + ext_of('.7z'):
            log('%s: extraindo %s' % (name, a))
            if not dry and extract_archive(os.path.join(folder, a), folder, log) and delete_src:
                os.remove(os.path.join(folder, a))
    made, src = None, None
    if not ext_of('.cue'):
        if ext_of('.chd'):
            src = os.path.join(folder, ext_of('.chd')[0]); log('%s: convertendo %s (chdman, sem perda)' % (name, os.path.basename(src)))
            made = None if dry else chd_to_cue(src, log)
        elif ext_of('.nrg'):
            src = os.path.join(folder, ext_of('.nrg')[0]); log('%s: convertendo %s (Nero)' % (name, os.path.basename(src)))
            made = None if dry else nrg_to_cue(src, log)
        elif ext_of('.img') and ext_of('.ccd'):
            src = os.path.join(folder, ext_of('.img')[0]); log('%s: criando o .cue de %s (CloneCD)' % (name, os.path.basename(src)))
            made = None if dry else ccd_to_cue(os.path.join(folder, ext_of('.ccd')[0]), src, log)
            src = None      # o .img continua sendo o disco
        elif ext_of('.iso') or ext_of('.img') or ext_of('.bin'):
            data = (ext_of('.iso') or ext_of('.img') or ext_of('.bin'))[0]
            aud = [f for f in lst() if os.path.splitext(f)[1].lower() in AUDIO_CONV_EXT + ('.wav',)]
            if not ext_of('.iso'):
                aud += [f for f in ext_of('.bin') if f != data]
            log('%s: criando o .cue (%s%s)' % (name, data, ' + %d faixa(s) de audio' % len(aud) if aud else ''))
            made = None if dry else raw_to_cue(os.path.join(folder, data), log, aud)
        elif ext_of('.mds') or ext_of('.mdf'):
            log('%s: .mdf/.mds (Alcohol) nao e suportado: converta para .bin/.cue' % name); return False
        else:
            return False
        if made and src and delete_src:
            os.remove(src); log('  %s apagado' % os.path.basename(src))
        if dry:
            return True
    cues = ext_of('.cue')
    if not cues:
        return False
    if len(cues) > 1:
        log('%s: ATENCAO, %d arquivos .cue (o SD Loader usa o primeiro que achar): deixe so um' % (name, len(cues)))
    try:
        return cue_fix(folder, os.path.join(folder, cues[0]), dry, lambda s: log(name + s), fresh=bool(made))
    except Exception as e:
        log('%s: erro ao conferir o .cue (%s)' % (name, str(e)[:100])); return False


def loose_to_folders(root, dry, log):
    """Jogo solto na raiz (Jogo.cue + Jogo.bin, Jogo.chd...) vai para uma pasta com o nome dele."""
    files = [f for f in os.listdir(root) if os.path.isfile(os.path.join(root, f)) and not f.startswith(('.', '_'))
             and os.path.splitext(f)[1].lower() in ('.cue', '.iso', '.chd', '.nrg', '.img', '.ccd', '.sub', '.bin', '.zip', '.7z')]
    groups = {}
    for f in sorted(files, key=lambda x: (not x.lower().endswith('.cue'), x.lower())):
        if any(f in g for g in groups.values()):
            continue
        stem = os.path.splitext(f)[0]
        g = groups.setdefault(stem, [])
        g.append(f)
        if f.lower().endswith('.cue'):
            try:
                for ff in cue_read(os.path.join(root, f)):
                    p = find_file(root, ff[0])
                    if p and os.path.basename(p) not in g:
                        g.append(os.path.basename(p))
            except Exception:
                pass
        for o in files:
            if o not in g and os.path.splitext(o)[0] == stem:
                g.append(o)
    for stem, g in groups.items():
        dest = os.path.join(root, stem.strip().rstrip('.'))
        log('raiz: %s -> pasta %s/' % (', '.join(g), os.path.basename(dest)))
        if dry:
            continue
        os.makedirs(dest, exist_ok=True)
        for f in g:
            if os.path.exists(os.path.join(root, f)) and not os.path.exists(os.path.join(dest, f)):
                shutil.move(os.path.join(root, f), os.path.join(dest, f))


def prepare_discs(root, dry=False, delete_src=False):
    """Passo 1: os jogos no formato que o SD Loader le. Devolve quantas pastas foram mexidas."""
    msgs = []
    log = lambda s: (msgs.append(s), print('  ' + s))
    loose_to_folders(root, dry, log)
    for d in sorted(os.listdir(root), key=str.lower):
        p = os.path.join(root, d)
        if not os.path.isdir(p) or d.startswith(('_', '.')) or d.lower() in SKIP:
            continue
        try:
            if any(os.path.splitext(f)[1].lower() in DISC_EXT for f in os.listdir(p)):
                disc_folder(p, dry, delete_src, log)
        except OSError as e:
            log('%s: %s' % (d, e))
    return len(msgs)


# ------------------------------------------------------------------ principal
def same_file(path, data):
    try:
        return os.path.getsize(path) == len(data) and open(path, 'rb').read() == data
    except OSError:
        return False


def put(path, data, dry):
    """grava so se mudou. 1 = gravou."""
    if same_file(path, data):
        return 0
    if not dry:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, 'wb').write(data)
    return 1


def pak_name(g):
    """o nome do jogo no pak: Latin-1 (como o menu le o ngcdgamelist.ode), 31 letras + 0"""
    b = bytes(ord(c) if ord(c) < 256 else 63 for c in g)[:31]
    return b + bytes(32 - len(b))


def build_pak(kinds, items):
    """menu 70: o pak do .media (como o do 3DO): 'NGPK', versao 1, jogos, vagas, letras (6), por jogo nome (32) +
    vagas x (onde, tamanho); depois os .ngi (endereco par)."""
    import struct
    esz = 32 + 8 * len(kinds)
    head = 16 + esz * len(items)
    idx, data, at = bytearray(), bytearray(), head
    for g, fs in items:
        idx += pak_name(g)
        for f in fs:
            if f:
                idx += struct.pack('>II', at, len(f))
                data += f + (b'\0' if len(f) & 1 else b'')
                at += len(f) + (len(f) & 1)
            else:
                idx += bytes(8)
    hdr = b'NGPK' + struct.pack('>HHH', 1, len(items), len(kinds)) + kinds.encode().ljust(6, b'\0')
    return hdr + bytes(idx) + bytes(data)


def write_paks(M, games, dry):
    """.media/covers/cover.pak (as 5 capas) e .media/screenshots/screenshots.pak, dos arquivos soltos (que ficam)."""
    n = 0
    for sub, name, kinds, dirs in (('covers', 'cover.pak', 'CGLKN', ('covers_full', 'covers', 'covers128', 'covers_mini', 'covers96')),
                                   ('screenshots', 'screenshots.pak', 'S', ('screenshots',))):
        items = []
        for g in games:
            fs = []
            for d in dirs:
                p = os.path.join(M, d, g + '.ngi')
                try:
                    f = open(p, 'rb').read()
                    fs.append(f if f[:3] == b'NGI' else None)
                except OSError:
                    fs.append(None)
            if any(fs):
                items.append((g, fs))
        if not items:
            continue
        pk = build_pak(kinds, items)
        w = put(os.path.join(M, sub, name), pk, dry)
        n += w
        print('  %s/%s: %d jogos, %d KB%s' % (sub, name, len(items), len(pk) // 1024, '' if w else ' (igual)'))
    return n


PAK_DIRS = (('covers', 'cover.pak', ('covers_full', 'covers', 'covers128', 'covers_mini', 'covers96')),
            ('screenshots', 'screenshots.pak', ('screenshots',)))


def read_pak(path):
    """{nome Latin-1: {letra: bytes}} do pak (ou None)"""
    import struct
    try:
        b = open(path, 'rb').read()
    except OSError:
        return None
    if b[:4] != b'NGPK':
        return None
    n, sl = struct.unpack_from('>HH', b, 6)
    kinds = b[10:10 + sl].decode('latin-1')
    out = {}
    for i in range(n):
        e = 16 + (32 + 8 * sl) * i
        name = b[e:e + 32].split(b'\0')[0].decode('latin-1')
        v = {}
        for k in range(sl):
            o, l = struct.unpack_from('>II', b, e + 32 + 8 * k)
            if l:
                v[kinds[k]] = b[o:o + l]
        out[name] = v
    return out


def unpack_paks(M):
    """os paks do cartao viram arquivos soltos (so os que faltam); o nome do pak e Latin-1: acha a pasta do jogo igual"""
    for sub, name, dirs in PAK_DIRS:
        pk = read_pak(os.path.join(M, sub, name))
        if not pk:
            continue
        kinds = 'CGLKN' if sub == 'covers' else 'S'
        root = os.path.dirname(M)
        games = {pak_name(g).split(b'\0')[0].decode('latin-1'): g for g in games_of(root)}
        for nm, v in pk.items():
            g = games.get(nm, nm)
            for k, d in zip(kinds, dirs):
                if k in v:
                    p = os.path.join(M, d, g + '.ngi')
                    if not os.path.isfile(p):
                        os.makedirs(os.path.dirname(p), exist_ok=True)
                        open(p, 'wb').write(v[k])


def clean_loose(M):
    """formato PAK: apaga os .ngi soltos das capas e telas (ficam so os paks)"""
    n = 0
    for sub, name, dirs in PAK_DIRS:
        for d in dirs:
            p = os.path.join(M, d)
            if not os.path.isdir(p):
                continue
            for f in os.listdir(p):
                if f.lower().endswith('.ngi'):
                    try:
                        os.remove(os.path.join(p, f)); n += 1
                    except OSError:
                        pass
            if d != sub:
                try:
                    os.rmdir(p)
                except OSError:
                    pass
    return n


def kit_dir(kit, midias):
    """a pasta do kit (com boot/ e wad/): a dada, a das midias, a acima deste programa ou a deste programa."""
    here = os.path.dirname(os.path.abspath(sys.argv[0] or __file__))
    for d in ([kit] if kit else []) + [midias, os.path.dirname(here), here]:
        if d and (os.path.isfile(os.path.join(d, 'boot', 'BOOT.ISO')) or os.path.isdir(os.path.join(d, 'wad'))):
            return d
    return None


def boot_iso(kit):
    """o BOOT.ISO do kit; sem kit, monta um com os arquivos do menu que vem dentro deste programa."""
    if kit:
        p = os.path.join(kit, 'boot', 'BOOT.ISO')
        if os.path.isfile(p):
            d = open(p, 'rb').read()
            files = iso_files(p) or []
            if menu_version(files) >= int(MENU_VERSION or 0):
                return d, menu_version(files), 'kit'
    files = [(n, d) for n, d in menu_files() if not is_media_file(n)]
    return build_iso(files), menu_version(files), 'embutido'


def copy_boot(root, kit, dry):
    iso, ver, src = boot_iso(kit)
    dst = os.path.join(root, '.boot', 'BOOT.ISO')
    if same_file(dst, iso):
        print('Menu   : .boot/BOOT.ISO (menu %d) igual ao do cartao, nao copiei' % ver)
    else:
        put(dst, iso, dry)
        cue = os.path.join(kit, 'boot', 'BOOT.CUE') if kit else ''
        put(os.path.join(root, '.boot', 'BOOT.CUE'), open(cue, 'rb').read() if os.path.isfile(cue) else boot_cue().encode('ascii'), dry)
        print('Menu   : .boot/BOOT.ISO (menu %d, %s) copiado, %d KB' % (ver, src, len(iso) // 1024))
    ldr = card_loader(root)
    old = os.path.join(root, '_BOOT')
    if ldr and ldr < 17:
        print('  ATENCAO: o console esta com o loader antigo (NGC%d), que so procura o menu em _BOOT.' % ldr)
        print('           Atualize em Opcoes -> Atualizar o loader. Ate la, copie a pasta .boot como _BOOT.')
    elif ldr >= 17 and os.path.isdir(old):
        lk, nlk = os.path.join(old, 'LINKS.TXT'), os.path.join(root, '.boot', 'LINKS.TXT')
        if not dry:
            if os.path.isfile(lk) and not os.path.isfile(nlk):
                shutil.copy2(lk, nlk)
            shutil.rmtree(old, ignore_errors=True)
        print('  _BOOT antigo removido (o loader do console ja usa .boot)')


def copy_wad(root, kit, dry):
    wd = os.path.join(kit, 'wad') if kit else ''
    wads = sorted((os.path.join(wd, f) for f in os.listdir(wd) if f.lower().endswith('.wad')),
                  key=os.path.getmtime, reverse=True) if os.path.isdir(wd) else []
    if not wads:
        return
    w = wads[0]; d = open(w, 'rb').read(); name = os.path.basename(w)
    same, others = False, []
    for base in (root, os.path.join(root, '.wad'), os.path.join(root, 'wad')):
        if not os.path.isdir(base):
            continue
        for f in os.listdir(base):
            p = os.path.join(base, f)
            if os.path.isfile(p) and f.lower().endswith(('.wad', '.bak')):
                if same_file(p, d):
                    same = True
                elif base == root and f.lower().endswith('.wad') and f.lower() != name.lower():
                    others.append(f)
    if same:
        print('WAD    : %s igual ao do cartao, nao copiei' % name)
    else:
        put(os.path.join(root, name), d, dry)
        print('WAD    : %s copiado para a raiz (o console atualiza ao ligar, ou Opcoes -> Atualizar o loader)' % name)
    if others:
        print('  ATENCAO: outros .WAD na raiz (%s). Deixe so um: o MCU usa o primeiro que achar.' % ', '.join(others))


def gl_text(entries, big_ok):
    """.config/ngcdgamelist.ode, como a pagina: texto UTF-8, uma linha por jogo, TAB entre os campos, "-" = vazio."""
    cl = lambda v: latin1(re.sub(r'[\t\r\n]+', ' ', str(v or '')).strip()).decode('latin-1')
    L = ['#NGCD-ODE-GAMES1\ttotal=%d' % len(entries), '#pasta\ttitulo\tano\tpais\tgenero\tdesenvolvedora\tpublicadora\tmidias\tdescricao']
    for g, cov, sht, vid, i in entries:
        m = ('C' + ('L' if big_ok else '') if cov else '') + ('S' if sht else '') + ('V' if vid else '')
        f = [display_title(i.get('title')), i.get('year'), i.get('region'), i.get('genre'), i.get('developer'),
             i.get('publisher'), m, (i.get('description') or '')[:1000]]
        L.append('\t'.join([cl(g)] + [cl(v) or '-' for v in f]))
    return ('\r\n'.join(L) + '\r\n').encode('utf-8')


def merged(*maps):
    e, l = {}, {}
    for m in maps:
        for k, v in m[0].items(): e.setdefault(k, v)
        for k, v in m[1].items(): l.setdefault(k, []).extend(v)
    return e, l


def newer(a, b):
    """a (destino) existe e nao e mais velho que b (origem)."""
    return os.path.isfile(a) and (not b or os.path.getmtime(a) >= os.path.getmtime(b))


def main(root, midias=None, dry=False, offline=False, redo=False, do_cov=True, do_sht=True, do_vid=True,
         kit=None, do_disc=True, delete_src=False, do_boot=True, do_wad=True, pak=True):
    root = os.path.abspath(root)
    midias = os.path.abspath(midias) if midias else root
    kit = kit_dir(kit, midias)
    print('Cartao  : %s' % root)
    if midias != root:
        print('Midias  : %s' % midias)
    print('Kit     : %s' % (kit or '(nao achei boot/ e wad/: uso o menu que vem dentro deste programa)'))

    # 1) discos
    if do_disc:
        print('\nDiscos (formato que o SD Loader le):')
        if not prepare_discs(root, dry, delete_src):
            print('  tudo certo')

    games = games_of(root)
    links = read_links(root)
    print('\n%d jogo(s) no cartao' % len(games))
    if links:
        print('  %d jogo(s) ligado(s) pela pagina (.boot/LINKS.TXT)' % len(links))
    if len(games) > 200:
        print('  ATENCAO: %d jogos; o SD Loader lista so 200.' % len(games))
    seen = {}
    for g in games:
        seen.setdefault(g[:25].lower(), []).append(g)
    for k, a in seen.items():
        if len(a) > 1:
            print('  ATENCAO: estas pastas viram o mesmo nome no SD Loader (%s): %s' % (a[0][:25], ' | '.join(a)))
    longn = [g for g in games if len(g) > 25]
    if longn:
        print('  Aviso: %d pasta(s) com mais de 25 letras (o SD Loader mostra so o comeco)' % len(longn))

    # origens das midias: imagens/videos (pasta das midias, raiz antiga do cartao) e prontos (.ngi/.ngv)
    M = os.path.join(root, '.media')
    if not dry:
        unpack_paks(M)          # menu 70: o que esta nos paks volta a ser arquivo solto enquanto trabalha (o resto do
                                # programa sabe o que ja tem pelos arquivos); no fim vira pak de novo (ou fica solto)
    src_cov = find_dir(midias, {'covers', 'cover', 'capas', 'capa'}) or os.path.join(midias, 'covers')
    src_sht = find_dir(midias, {'screenshots', 'screenshot', 'telas', 'tela'}) or os.path.join(midias, 'screenshots')
    src_vid = find_dir(midias, {'videos', 'video'})
    cov_maps = merged(images_of(src_cov), images_of(os.path.join(root, 'covers')))
    sht_maps = merged(images_of(src_sht), images_of(os.path.join(root, 'screenshots')))
    vid_maps = merged(images_of(src_vid, VID_EXT), images_of(os.path.join(root, 'videos'), VID_EXT))
    pre_cov = merged(images_of(os.path.join(M, 'covers_full'), ('.ngi',)), images_of(os.path.join(midias, 'media', 'covers'), ('.ngi',)),
                     images_of(os.path.join(root, 'covers'), ('.ngi',)))
    pre_sht = merged(images_of(os.path.join(M, 'screenshots'), ('.ngi',)), images_of(os.path.join(midias, 'media', 'screenshots'), ('.ngi',)),
                     images_of(os.path.join(root, 'screenshots'), ('.ngi',)))
    pre_big = merged(images_of(os.path.join(midias, 'media', 'covers128'), ('.ngi',)))
    pre_mid = merged(images_of(os.path.join(midias, 'media', 'covers96'), ('.ngi',)))      # do converter_tudo (menu 62)
    pre_grid = merged(images_of(os.path.join(midias, 'media', 'covers64'), ('.ngi',)))    # do converter_tudo (menu 63)
    pre_mini = merged(images_of(os.path.join(midias, 'media', 'covers_mini'), ('.ngi',)))
    pre_vid = merged(images_of(os.path.join(M, 'videos'), ('.ngv',)), images_of(os.path.join(midias, 'media', 'videos'), ('.ngv',)),
                     images_of(os.path.join(root, 'videos'), ('.ngv',)))

    def mid_ready(g):         # a de 96 pronta do converter_tudo (media/covers96), se for valida
        p = fimg(pre_mid, g)
        if p:
            b = open(p, 'rb').read()
            if b[:3] == b'NGI' and b[5] == 6 and b[7] == 6 and b[9] <= 16 and b[11] <= 48:
                return b
        return None

    def ready(maps, g, wt, ht):   # a pronta do converter_tudo (covers64 4x4, covers_mini 2x2), se for valida
        p = fimg(maps, g)
        if p:
            b = open(p, 'rb').read()
            if b[:3] == b'NGI' and b[5] == wt and b[7] == ht:
                return b
        return None

    def fimg(maps, g):        # pelo jogo ligado primeiro, depois pelo nome da pasta
        l = links.get(norm(g))
        return (find_image(maps, l) if l else None) or find_image(maps, g)

    idx = None if offline or not (do_cov or do_sht) else remote_index()
    lang = card_lang(root)
    gl, dat, glsrc = gamelists(midias, lang)
    print('Textos : %d jogos no gamelist (%s, %s)' % (len(set(id(v) for v in gl.values())), lang, glsrc))
    if not dry:
        for d in ('covers_full', 'covers', 'covers128', 'covers_mini', 'covers96', 'screenshots', 'videos'):
            os.makedirs(os.path.join(M, d), exist_ok=True)
        for d in ('.config', '.saves', '.boot'):
            os.makedirs(os.path.join(root, d), exist_ok=True)

    # 2) videos novos ou trocados: todos de uma vez, um por nucleo
    vconv = 0
    if do_vid and not dry:
        jobs = []
        for g in games:
            vsrc = fimg(vid_maps, g)
            dst = os.path.join(M, 'videos', g + '.ngv')
            if not vsrc:
                continue
            pre = fimg(pre_vid, g)
            if not redo and (newer(dst, vsrc) or (pre and newer(pre, vsrc))):
                continue
            jobs.append((vsrc, dst))
        if jobs:
            print('Videos : convertendo %d (15 s cada, 96x72)...' % len(jobs))
            ok, err = convert_videos(jobs)
            vconv = len(ok)
            for (src, _), e in err:
                print('  ERRO no video %s: %s' % (os.path.basename(src), e))

    entries, miss = [], []
    n = {'cov': 0, 'sht': 0, 'vid': 0, 'conv': 0, 'dl': 0, 'txt': 0, 'files': 0}
    big_ok = True
    for g in games:
        got = {}
        for kind, maps, pre, rfolder, on in (('cover', cov_maps, pre_cov, 'Named_Boxarts', do_cov),
                                             ('shot', sht_maps, pre_sht, 'Named_Snaps', do_sht)):
            full = os.path.join(M, 'covers_full' if kind == 'cover' else 'screenshots', g + '.ngi')
            src = fimg(maps, g) if on else None
            if on and not src and idx and not os.path.isfile(full) and not fimg(pre, g):
                rb = (remote_find(idx, rfolder, links[norm(g)]) if norm(g) in links else None) or remote_find(idx, rfolder, g)
                if rb:
                    dest = os.path.join(src_cov if kind == 'cover' else src_sht, g + '.png')
                    if dry:
                        print('  [teste] baixaria %s/%s.png' % (rfolder, rb))
                    else:
                        try:
                            download(rfolder, rb, dest); n['dl'] += 1; src = dest
                            print('  baixada: %s (%s)' % (os.path.basename(dest), 'capa' if kind == 'cover' else 'tela'))
                        except Exception as e:
                            print('  falha ao baixar %s: %s' % (rb, e))
            data, fresh = None, False
            if src and (redo or not newer(full, src)):
                if dry:
                    print('  [teste] converteria %s' % os.path.basename(src)); data = b'x'
                else:
                    try:
                        data = convert(src, kind); fresh = True; n['conv'] += 1
                    except Exception as e:
                        print('  ERRO ao converter %s: %s' % (os.path.basename(src), str(e)[:80]))
            if data is None:
                p = full if os.path.isfile(full) else fimg(pre, g)
                if p:
                    data = open(p, 'rb').read()
                    fresh = os.path.abspath(p) != os.path.abspath(full)
            if not data:
                got[kind] = False
                if on and not src:
                    miss.append((g, kind))
                continue
            got[kind] = True
            if dry:
                continue
            if kind == 'shot':
                n['files'] += put(full, data, dry); n['sht'] += 1
                continue
            n['cov'] += 1
            n['files'] += put(full, data, dry)
            # as outras capas (pequena, grande e a capinha): refaz se a capa mudou ou se faltam
            for sub, mk in (('covers', lambda: ready(pre_grid, g, 4, 4) or (convert(src, 'grid') if src else grid_from_ngi(data))),
                            ('covers_mini', lambda: ready(pre_mini, g, 2, 2) or (mini_ngi(src) if src else mini_from_ngi(data))),
                            ('covers96', lambda: mid_ready(g) or (convert(src, 'mid') if src else mid_from_ngi(data))),   # menu 62
                            ('covers128', None)):
                dst = os.path.join(M, sub, g + '.ngi')
                if not fresh and os.path.isfile(dst):
                    continue
                try:
                    if mk is None:
                        pb = None if src else fimg(pre_big, g)
                        if pb:
                            b = open(pb, 'rb').read()
                            if b[:3] != b'NGI' or b[5] != 8 or b[7] != 8:
                                pb = None
                        b = b if pb else (convert(src, 'big') if src else big_from_ngi(data))
                    else:
                        b = mk()
                    n['files'] += put(dst, b, dry)
                except Exception as e:
                    if sub == 'covers128':
                        big_ok = False
                    print('  %s de %s: %s' % (sub, g, str(e)[:60]))
        vid = False
        if do_vid:
            dst = os.path.join(M, 'videos', g + '.ngv')
            if not os.path.isfile(dst):
                pre = fimg(pre_vid, g)
                if pre and not dry:
                    d = open(pre, 'rb').read()
                    if d[:4] == b'NGV1':
                        n['files'] += put(dst, d, dry)
            vid = os.path.isfile(dst) or (dry and bool(fimg(vid_maps, g) or fimg(pre_vid, g)))
            if vid:
                n['vid'] += 1
            elif not fimg(vid_maps, g):
                miss.append((g, 'video'))
        else:
            vid = os.path.isfile(os.path.join(M, 'videos', g + '.ngv'))
        info = game_info(links.get(norm(g), g), gl, dat)
        if norm(g) in links and region_codes(g):
            info['region'] = region_codes(g)
        if info.get('title'):
            n['txt'] += 1
        else:
            miss.append((g, 'text'))
        entries.append((g, got.get('cover') or os.path.isfile(os.path.join(M, 'covers_full', g + '.ngi')),
                        got.get('shot') or os.path.isfile(os.path.join(M, 'screenshots', g + '.ngi')), vid, info))

    # 3) textos
    gl_bytes = gl_text(entries, big_ok)
    wrote = put(os.path.join(root, '.config', 'ngcdgamelist.ode'), gl_bytes, dry)
    print('Capas: %d   telas: %d   convertidas agora: %d   baixadas: %d   com texto: %d' % (n['cov'], n['sht'], n['conv'], n['dl'], n['txt']))
    if do_vid:
        print('Videos: %d   convertidos agora: %d' % (n['vid'], vconv))
    if pak:     # menu 70: formato PAK (padrao, como o 3DO): os 2 paks e nada solto
        n['files'] += write_paks(M, [e[0] for e in entries if e[1] or e[2]], dry)
        if not dry:
            print('  arquivos soltos apagados: %d' % clean_loose(M))
    elif not dry:
        for sub, name in (('covers', 'cover.pak'), ('screenshots', 'screenshots.pak')):
            try:
                os.remove(os.path.join(M, sub, name)); print('  %s/%s apagado (formato individual)' % (sub, name))
            except OSError:
                pass
    print('.media: %d arquivo(s) gravado(s)   .config/ngcdgamelist.ode: %s' % (n['files'], 'gravado' if wrote else 'igual, nao gravei'))
    for old in ('MEDIA.PRG',):          # o indice antigo (menus ate 51): o menu de hoje le o .config
        p = os.path.join(M, old)
        if os.path.isfile(p) and not dry:
            os.remove(p)
    if os.path.isdir(os.path.join(M, 'texts')) and not dry:
        shutil.rmtree(os.path.join(M, 'texts'), ignore_errors=True)
    olds = [d for d in ('covers', 'screenshots', 'videos') if os.path.isdir(os.path.join(root, d))]
    if olds:
        print('  (as pastas %s na raiz do cartao sao do esquema antigo: o que tinha nelas ja foi para a .media; pode apagar)' % ', '.join(olds))

    # 4) menu e 5) firmware
    if do_boot:
        copy_boot(root, kit, dry)
    if do_wad:
        copy_wad(root, kit, dry)

    if not dry:
        for kind, fn in (('cover', 'missing_cover.txt'), ('shot', 'missing_screenshot.txt'), ('text', 'missing_text.txt'),
                         ('video', 'missing_video.txt')):
            lst = sorted(g for g, k in miss if k == kind)
            p = os.path.join(midias, fn)
            if lst:
                open(p, 'w', encoding='utf-8-sig', newline='\r\n').write(
                    '# %d jogo(s) sem %s (nomeie o arquivo igual a pasta do jogo):\n' % (len(lst), {'cover': 'capa', 'shot': 'tela', 'text': 'texto no gamelist', 'video': 'video'}[kind]) + '\n'.join(lst) + '\n')
            elif os.path.isfile(p):
                os.remove(p)
    print('[teste] nada foi gravado (sem --teste, faria o que esta acima).' if dry else 'Pronto. Ponha o cartao no SD Loader e ligue o console.')


# ------------------------------------------------------------------ assistente
def _ini_load():
    d = {}
    try:
        for ln in open(INI_PATH, encoding='utf-8'):
            if '=' in ln and not ln.startswith('#'):
                k, v = ln.split('=', 1); d[k.strip()] = v.strip()
    except OSError:
        pass
    return d


def _ini_save(d):
    try:
        with open(INI_PATH, 'w', encoding='utf-8') as f:
            f.write('# generate_usb.ini - respostas do assistente (apague para voltar ao padrao)\n')
            for k, v in d.items():
                f.write('%s=%s\n' % (k, v))
    except OSError:
        pass


def _ask(txt, default=''):
    try:
        r = input('%s%s: ' % (txt, (' [%s]' % default) if default else '')).strip().strip('"')
    except EOFError:
        return default
    return r or default


def _yn(txt, default):
    while True:
        r = _ask(txt + ('  (S/n)' if default else '  (s/N)')).lower()
        if not r: return default
        if r[:1] in ('s', 'y'): return True
        if r[:1] == 'n': return False


def wizard():
    ini = _ini_load()
    print('=' * 66)
    print('  generate_usb - Neo Geo CD SD Loader (menu CR)')
    print('  Enter aceita o valor entre [ ]')
    print('=' * 66)
    while True:
        root = _ask('\n1) Pasta do CARTAO SD (onde ficam as pastas dos jogos)', ini.get('root', ''))
        if root and os.path.isdir(root):
            break
        print('   pasta nao encontrada')
    midias = _ask('2) Pasta das MIDIAS (covers/ e screenshots/)  [Enter = o proprio cartao]', ini.get('midias', ''))
    if midias and not os.path.isdir(midias):
        print('   pasta nao encontrada: usando o cartao'); midias = ''
    do_cov = _yn('3) Gerar as CAPAS?', ini.get('docov', '1') == '1')
    do_sht = _yn('   Gerar as TELAS (screenshots)?', ini.get('dosht', '1') == '1')
    do_vid = _yn('   Gerar os VIDEOS (videos/<jogo>.mp4, a previa da lista)?', ini.get('dovid', '1') == '1')
    online = _yn('4) BAIXAR do libretro as imagens que faltarem?', ini.get('online', '1') == '1')
    redo = _yn('5) Converter de novo TODAS as imagens? (N = so as novas ou trocadas)', False)
    do_disc = _yn('6) Acertar os DISCOS (chd, nrg, img, iso+mp3, zip -> .cue que o SD Loader le)?', ini.get('dodisc', '1') == '1')
    delete_src = do_disc and _yn('   Apagar o .chd/.nrg/.zip original depois de converter?', ini.get('apagar', '0') == '1')
    pak = _yn('   Formato das capas e telas: PAK (um arquivo so, como o 3DO; N = um arquivo por imagem)?', ini.get('pak', '1') == '1')
    kit = _ask('7) Pasta do KIT (boot/BOOT.ISO e wad/)  [Enter = a pasta acima deste programa]', ini.get('kit', ''))
    if kit and not os.path.isdir(kit):
        print('   pasta nao encontrada: procurando sozinho'); kit = ''
    _ini_save({'root': root, 'midias': midias, 'kit': kit, 'docov': int(do_cov), 'dosht': int(do_sht), 'dovid': int(do_vid),
               'online': int(online), 'dodisc': int(do_disc), 'apagar': int(delete_src), 'pak': int(pak)})
    flags = (['--midias', '"%s"' % midias] if midias else []) + (['--kit', '"%s"' % kit] if kit else []) + ([] if online else ['--offline']) + \
            (['--refazer'] if redo else []) + ([] if do_cov else ['--pular-capas']) + ([] if do_sht else ['--pular-telas']) + \
            ([] if do_vid else ['--pular-videos']) + ([] if do_disc else ['--pular-discos']) + (['--apagar-origem'] if delete_src else []) + ([] if pak else ['--individual'])
    print('\nComando equivalente (para a proxima vez, sem perguntas):')
    print('   py generate_usb.py "%s" %s\n' % (root, ' '.join(flags)))
    main(root, midias or None, False, not online, redo, do_cov, do_sht, do_vid, kit or None, do_disc, delete_src, pak=pak)
    try:
        input('\nConcluido. Enter para fechar.')
    except EOFError:
        pass


if __name__ == '__main__':
    argv = sys.argv[1:]
    if not argv:
        wizard(); sys.exit(0)
    low = [a.lower() for a in argv]
    opt = {}
    for k in ('--midias', '--kit'):
        if k in low:
            i = low.index(k)
            opt[k] = argv[i + 1] if i + 1 < len(argv) else None
    args = [a for a in argv if not a.startswith('--') and a not in opt.values()]
    flags = set(low)
    main(args[0] if args else '.', opt.get('--midias'), '--teste' in flags, '--offline' in flags, '--refazer' in flags,
         '--pular-capas' not in flags, '--pular-telas' not in flags, '--pular-videos' not in flags,
         opt.get('--kit'), '--pular-discos' not in flags, '--apagar-origem' in flags,
         '--sem-menu' not in flags, '--sem-wad' not in flags, '--individual' not in flags)
